/** The parts of the project an export reads (null = not read); the output changes only when one of them does. */
export interface ExportInputs {
  grammar: Grammar | null
  prec: Prec | null
  names: Names | null
}

export function exportInputs(kind: ExportKind, data: ProjectData, grammar: Grammar): ExportInputs {
  const def = EXPORTS.find((e) => e.kind === kind)!
  return {
    grammar: def.source === 'grammar' ? grammar : null,
    prec: def.source === 'prec' ? data.prec : null,
    names: 'names' in def ? data.names : null,
  }
}

const SYM_NAMES: Record<string, string> = {
  '+': 'PLUS', '-': 'MINUS', '*': 'MUL', '/': 'DIV', '%': 'MOD', '(': 'LPAREN', ')': 'RPAREN',
  '[': 'LBRACKET', ']': 'RBRACKET', '{': 'LBRACE', '}': 'RBRACE', ',': 'COMMA', ';': 'SEMICOLON',
  ':': 'COLON', '.': 'DOT', '=': 'ASSIGN', '==': 'EQ', '!=': 'NEQ', '<': 'LT', '<=': 'LE', '>': 'GT',
  '>=': 'GE', '!': 'NOT', '&&': 'AND', '||': 'OR', $: 'EOF', '?': 'QUESTION', '=>': 'ARROW',
  '->': 'ARROW', '&': 'AMP', '|': 'PIPE', '^': 'CARET', '~': 'TILDE', '#': 'HASH', '@': 'AT',
}

const GEN_HEADER = 'Generated by tools/table-maker'
const MIME = {
  md: 'text/markdown;charset=utf-8',
  csv: 'text/csv;charset=utf-8',
  tex: 'text/x-tex;charset=utf-8',
  c: 'text/x-c;charset=utf-8',
}

function nameMap(text: string) {
  const m = new Map<string, string>()
  text.split('\n').forEach((ln) => {
    const t = symbolList(ln)
    if (t.length >= 2) m.set(t[0], t[1])
  })
  return m
}

// Unique C identifiers for the given symbols, all starting with the prefix (a custom name gets it too unless it
// already starts with it). `used` holds the identifiers already taken in the header and is extended.
function cNames(symbols: string[], prefix: string, mapText: string, used: Set<string>) {
  const map = nameMap(mapText)
  return symbols.map((sym) => {
    const custom = map.get(sym)
    let name: string
    if (custom) name = custom.startsWith(prefix) ? custom : prefix + custom
    else {
      let base =
        SYM_NAMES[sym] ??
        sym
          .replace(/^<(.+)>$/, '$1')
          .replace(/'/g, '_PRIME')
          .replace(/[^A-Za-z0-9]+/g, '_')
          .replace(/^_+|_+$/g, '')
          .toUpperCase()
      if (!base) base = 'SYM'
      name = prefix + (/^[0-9]/.test(base) ? '_' + base : base)
    }
    let unique = name
    for (let i = 2; used.has(unique); i++) unique = `${name}_${i}`
    used.add(unique)
    return unique
  })
}

const cComment = (s: string) => s.replace(/\*\//g, '* /')
const mdCell = (s: string | number) => String(s).replace(/\|/g, '\\|')
const csvCell = (s: string) => (/[",\n;]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s)
const TEX: Record<string, string> = {
  '\\': '\\textbackslash{}', '{': '\\{', '}': '\\}', $: '\\$', '&': '\\&', '#': '\\#', '%': '\\%', _: '\\_',
  '^': '\\textasciicircum{}', '~': '\\textasciitilde{}', '<': '\\textless{}', '>': '\\textgreater{}', '|': '\\textbar{}',
}
const texEsc = (s: string) => s.replace(/[\\{}$&#%_^~<>|]/g, (c) => TEX[c])

function mdTable([header, ...rows]: string[][]) {
  return (
    [
      `| ${header.map(mdCell).join(' | ')} |`,
      `|${header.map(() => ' :-: ').join('|')}|`,
      ...rows.map((r) => `| ${r.map(mdCell).join(' | ')} |`),
    ].join('\n') + '\n'
  )
}

const csvTable = (rows: string[][]) => rows.map((r) => r.map(csvCell).join(',')).join('\n') + '\n'

function texTable([header, ...rows]: string[][]) {
  const spec = '|' + header.map(() => 'c').join('|') + '|'
  const line = (r: string[], mathRel: boolean) =>
    r.map((c, i) => (i > 0 && mathRel && /^[<=>]$/.test(c) ? `$${c}$` : texEsc(c))).join(' & ') + ' \\\\ \\hline'
  return [`% ${GEN_HEADER}`, `\\begin{tabular}{${spec}}`, '\\hline', line(header, false), ...rows.map((r) => line(r, true)), '\\end{tabular}', ''].join('\n')
}

const texTablePreview = (grid: string[][]): TexPreview => ({ type: 'table', header: grid[0], rows: grid.slice(1) })

const text = (name: string, mime: string, body: string, preview?: TexPreview): ExportResult =>
  preview ? { type: 'text', name, mime, text: body, preview } : { type: 'text', name, mime, text: body }
const error = (message: string): ExportResult => ({ type: 'error', error: message })

type Source = { grammar: Grammar; prec: Prec; names: Names }
type Builder = (src: Source) => ExportResult

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "could you add a tab where i will be able to define properties"
// Changes: G = (N, T, P, S) as Markdown (with a symbol table) or as LaTeX.
const definition =
  (build: (g: Grammar) => ExportResult): Builder =>
  ({ grammar: g }) =>
    !g.rules.length && !g.N.length && !g.T.length ? error('Definícia gramatiky je prázdna.') : build(g)

const ll =
  (build: (a: LLAnalysis, src: Source) => ExportResult): Builder =>
  (src) =>
    src.grammar.ll ? build(src.grammar.ll, src) : error('LL gramatika je prázdna.')

const prec =
  (build: (model: TableModel, src: Source) => ExportResult): Builder =>
  (src) =>
    src.prec.terminals.length ? build(precTableModel(src.prec), src) : error('Precedenčná tabuľka je prázdna.')

function defMarkdown(g: Grammar): ExportResult {
  const code = (s: string) => `\`${s}\``
  const set = (xs: string[]) => (xs.length ? `{ ${xs.map(code).join(', ')} }` : '∅')
  let md = `## Gramatika G = (N, T, P, S)\n\n- N = ${set(g.N)}\n- T = ${set(g.T)}\n- S = ${g.S ? code(g.S) : '–'}\n`
  md += `\n### P\n\n${g.rules.map((r, i) => `${i + 1}. ${code(ruleText(r))}`).join('\n') || '∅'}\n`
  const rows = [...g.N.map((s) => [s, 'N']), ...g.T.map((s) => [s, 'T'])].map(([s, k]) => [code(s), k, g.notes.get(s) ?? ''])
  if (rows.some((r) => r[2])) md += `\n### Symboly\n\n${mdTable([['Symbol', 'Druh', 'Popis'], ...rows])}`
  return text('grammar.md', MIME.md, md)
}

function defTex(g: Grammar): ExportResult {
  const tt = (s: string) => `\\texttt{${texEsc(s)}}`
  const set = (xs: string[]) => (xs.length ? `\\{ ${xs.map(tt).join(', ')} \\}` : '\\emptyset')
  const rhs = (xs: string[]) => (xs.length ? xs.map(tt).join('\\,') : '\\varepsilon')
  const tex = [
    `% ${GEN_HEADER}`,
    '\\begin{align*}',
    'G &= (N, T, P, S) \\\\',
    `N &= ${set(g.N)} \\\\`,
    `T &= ${set(g.T)} \\\\`,
    `S &= ${g.S ? tt(g.S) : '-'}`,
    '\\end{align*}',
    ...(g.rules.length ? ['\\begin{enumerate}', ...g.rules.map((r) => `  \\item $${tt(r.lhs)} \\rightarrow ${rhs(r.rhs)}$`), '\\end{enumerate}'] : []),
    '',
  ]
  return text('grammar.tex', MIME.tex, tex.join('\n'), { type: 'def', N: g.N, T: g.T, S: g.S, rules: g.rules })
}

function llHeader(a: LLAnalysis, names: Names): ExportResult {
  const ntCount = names.ntPrefix + 'COUNT'
  const tCount = names.tPrefix + 'COUNT'
  const used = new Set(['ll_nonterminal_t', 'll_terminal_t', 'LL_TABLE', ntCount, tCount])
  const nt = cNames(a.N, names.ntPrefix, names.map, used)
  const t = cNames(a.cols, names.tPrefix, names.map, used)
  let c = `/* ${GEN_HEADER} */\n\n/* Rules:\n`
  a.rules.forEach((r, i) => {
    c += ` * ${String(i + 1).padStart(3)}: ${cComment(ruleText(r))}\n`
  })
  c += ' */\n\n'
  c += `typedef enum {\n${nt.map((n, i) => `    ${n}, /* ${cComment(a.N[i])} */`).join('\n')}\n    ${ntCount}\n} ll_nonterminal_t;\n\n`
  c += `typedef enum {\n${t.map((n, i) => `    ${n}, /* ${cComment(a.cols[i])} */`).join('\n')}\n    ${tCount}\n} ll_terminal_t;\n\n`
  c += `/* Rule number (1-based), 0 = syntax error */\nstatic const int LL_TABLE[${ntCount}][${tCount}] = {\n`
  a.N.forEach((A, i) => {
    const entries: string[] = []
    a.cols.forEach((col, j) => {
      const cell = a.table.get(A)!.get(col)
      if (cell) entries.push(`[${t[j]}] = ${cell[0]}${cell.length > 1 ? ` /* CONFLICT: ${cell.join(', ')} */` : ''}`)
    })
    c += `    [${nt[i]}] = { ${entries.join(', ')} },\n`
  })
  return text('ll_table.h', MIME.c, c + '};\n')
}

function precHeader(model: TableModel, names: Names): ExportResult {
  const cols = model.header.slice(1)
  const count = names.precPrefix + 'COUNT'
  const used = new Set(['PREC_NONE', 'PREC_LT', 'PREC_EQ', 'PREC_GT', 'prec_rel_t', 'prec_terminal_t', 'PREC_TABLE', count])
  const cn = cNames(cols, names.precPrefix, names.map, used)
  const rel: Record<string, string> = { '<': 'PREC_LT', '=': 'PREC_EQ', '>': 'PREC_GT' }
  let c = `/* ${GEN_HEADER} */\n\n`
  c += 'typedef enum {\n    PREC_NONE = 0, /* empty cell = syntax error */\n    PREC_LT,\n    PREC_EQ,\n    PREC_GT\n} prec_rel_t;\n\n'
  c += `typedef enum {\n${cn.map((n, i) => `    ${n}, /* ${cComment(cols[i])} */`).join('\n')}\n    ${count}\n} prec_terminal_t;\n\n`
  c += `/* [terminal on stack][input token] */\nstatic const prec_rel_t PREC_TABLE[${count}][${count}] = {\n`
  model.rows.forEach((row, i) => {
    const entries = row.cells.flatMap((cell, j) => (cell.text ? [`[${cn[j]}] = ${rel[cell.text]}`] : []))
    c += `    [${cn[i]}] = { ${entries.join(', ')} },\n`
  })
  return text('prec_table.h', MIME.c, c + '};\n')
}

const BUILDERS: Record<ExportKind, Builder> = {
  'def-md': definition(defMarkdown),
  'def-tex': definition(defTex),
  'll-md': ll((a) => {
    const rules = a.rules.map((r, i) => `${i + 1}. \`${ruleText(r)}\``).join('\n')
    return text('ll-table.md', MIME.md, `## LL tabuľka\n\n${mdTable(tableGrid(llTableModel(a)))}\n### Pravidlá\n\n${rules}\n`)
  }),
  'll-sets-md': ll((a) => {
    const sets = mdTable(tableGrid(llSetsTableModel(a)))
    const pred = mdTable(tableGrid(llPredictTableModel(a)))
    return text('ll-sets.md', MIME.md, `## Empty, First, Follow\n\n${sets}\n## Predict\n\n${pred}`)
  }),
  'll-csv': ll((a) => text('ll-table.csv', MIME.csv, csvTable(tableGrid(llTableModel(a))))),
  'll-tex': ll((a) => {
    const grid = tableGrid(llTableModel(a))
    return text('ll-table.tex', MIME.tex, texTable(grid), texTablePreview(grid))
  }),
  'll-c': ll((a, src) => llHeader(a, src.names)),
  'll-png': ll((a) => ({ type: 'image', name: 'll-table.png', table: llTableModel(a) })),
  'prec-md': prec((m) => text('prec-table.md', MIME.md, `## Precedenčná tabuľka\n\n${mdTable(tableGrid(m))}`)),
  'prec-csv': prec((m) => text('prec-table.csv', MIME.csv, csvTable(tableGrid(m)))),
  'prec-tex': prec((m) => text('prec-table.tex', MIME.tex, texTable(tableGrid(m)), texTablePreview(tableGrid(m)))),
  'prec-c': prec((m, src) => precHeader(m, src.names)),
  'prec-png': prec((m) => ({ type: 'image', name: 'prec-table.png', table: m })),
}

/** The export of the given kind: text (file name, media type, optional LaTeX preview), an image table, or an error. */
export function buildExport(kind: ExportKind, data: ProjectData, grammar: Grammar): ExportResult {
  return BUILDERS[kind]({ grammar, prec: data.prec, names: data.names })
}

export function downloadText(name: string, text: string, type = 'text/plain;charset=utf-8') {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const link = document.createElement('a')
  link.href = url
  link.download = name
  document.body.appendChild(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

// AI generated by: Claude Code / claude-opus-5-5
